 "content": "def transform(grid):
    """Shear every nonzero cell left by its distance above the lowest occupied row."""
    height = len(grid)
    width = len(grid[0]) if height else 0
    occupied_rows = [r for r, row in enumerate(grid) if any(row)]
    if not occupied_rows:
        return [row[:] for row in grid]
    bottom = max(occupied_rows)
    out = [[0 for _ in range(width)] for _ in range(height)]
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, value in enumerate(row):
            nc = c + shift
            if value and 0 <= nc < width:
                out[r][nc] = value
    return out
